package com.example.yuejie;
import android.app.*;import android.content.*;import android.os.*;import android.view.*;import android.graphics.*;import org.json.*;import java.io.*;import java.util.*;
/** Native gestures and raster evidence, kept outside the shipping APK. */
public class TurnChecks extends DeviceChecks {
 JSONObject originalPrefs,originalPosition;String book="6982529841564224526";LocalLibrary db;
 void restorePrefs(JSONObject state)throws Exception{SharedPreferences.Editor edit=getTargetContext().getSharedPreferences("ReaderActivity",0).edit().clear();for(Iterator<String> it=state.keys();it.hasNext();){String k=it.next();Object v=state.get(k);if(k.equals("brightness")&&v instanceof Number)edit.putFloat(k,((Number)v).floatValue());else if(v instanceof Boolean)edit.putBoolean(k,(Boolean)v);else if(v instanceof Integer)edit.putInt(k,(Integer)v);else if(v instanceof Number)edit.putFloat(k,((Number)v).floatValue());else edit.putString(k,v.toString());}edit.commit();}
 void launchReader()throws Exception{launchMain();reader=(ReaderActivity)startActivitySync(new Intent(getTargetContext(),ReaderActivity.class).putExtra("book_id",book).putExtra("book_name","我在精神病院学斩神").putExtra("chapter_index",0).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));ready();ui(()->{reader.settings.comments=false;reader.settings.font=20;reader.settings.spacing=1;reader.settings.serif=false;reader.settings.night=false;reader.settings.theme=1;reader.settingChanged();});ready();waitFor(()->reader.layouts.containsKey(1),40,"neighbor ready");}
 void select(PageTurnMode mode)throws Exception{int anchor=reader.anchor;ReaderPaginator layout=reader.surface.frame.layout;ui(()->reader.showSettings());tap(reader,mode.label);assertTrue(reader.settings.pageTurnMode==mode&&new ReaderSettings(getTargetContext()).pageTurnMode==mode,"mode persisted "+mode);assertTrue(layout==reader.surface.frame.layout&&anchor==reader.anchor,"mode change does not reflow or move anchor");ui(()->reader.hideOverlays());waitForIdleSync();SystemClock.sleep(150);}
 void page(int p){ui(()->{ReaderSurface.Frame f=reader.surface.frame;reader.commit(new ReaderSurface.Frame(f.id,f.title,reader.index,f.totalChapters,f.layout,p));});SystemClock.sleep(120);}
 Bitmap rendering(){final Bitmap[] out={null};ui(()->{out[0]=Bitmap.createBitmap(reader.surface.getWidth(),reader.surface.getHeight(),Bitmap.Config.ARGB_8888);reader.surface.draw(new Canvas(out[0]));});return out[0];}
 void hold(float x,float end,float y){ui(()->{long t=SystemClock.uptimeMillis();MotionEvent down=MotionEvent.obtain(t,t,0,x,y,0);reader.surface.dispatchTouchEvent(down);down.recycle();MotionEvent move=MotionEvent.obtain(t,t+300,2,end,y,0);reader.surface.dispatchTouchEvent(move);move.recycle();});}
 void cancelHold(){ui(()->{long t=SystemClock.uptimeMillis();MotionEvent e=MotionEvent.obtain(t,t+500,MotionEvent.ACTION_CANCEL,reader.surface.lastX,reader.surface.downY,0);reader.surface.dispatchTouchEvent(e);e.recycle();});}
 void oneMode(PageTurnMode mode)throws Exception{
  select(mode);page(2);reader.surface.animationNanos=0;reader.surface.animationFrames=0;int w=reader.surface.getWidth(),h=reader.surface.getHeight();float y=h*.72f;int original=reader.anchor,commits=reader.surface.commits;Bitmap before=rendering();int allocated=reader.surface.renderer instanceof PageTurnRenderer.Curl?((PageTurnRenderer.Curl)reader.surface.renderer).allocations:0;
  hold(w*.85f,w*.42f,y);Bitmap during=rendering();int changed=0;for(int yy=130;yy<h-100;yy+=7)for(int xx=30;xx<w-30;xx+=7)if(before.getPixel(xx,yy)!=during.getPixel(xx,yy))changed++;assertTrue(mode==PageTurnMode.NONE?changed==0:changed>100,"distinct moving/static render "+mode+" pixels="+changed);assertTrue(reader.anchor==original,"drag has no committed position");if(mode==PageTurnMode.SIMULATION){PageTurnRenderer.Curl curl=(PageTurnRenderer.Curl)reader.surface.renderer;assertTrue(curl.front!=null&&curl.next!=null,"real curl snapshots ready");assertTrue(curl.allocations==allocated,"no full-page allocation during drag");assertTrue(!curl.reflected.isEmpty()&&!curl.crease.isEmpty(),"folded back and Bezier geometry");}shot(mode.key+"-half-next");before.recycle();during.recycle();cancelHold();waitFor(()->!reader.surface.animating(),3,"cancel settles");assertTrue(reader.anchor==original&&reader.surface.commits==commits,"cancel retains progress");
  touch(w*.8f,y,w*.72f,y,600,false);waitFor(()->!reader.surface.animating(),3,"short rollback");assertTrue(reader.anchor==original,"short swipe rolls back");swipe(w*.85f,y,w*.15f,y,450);assertTrue(reader.surface.frame.pageIndex==3&&reader.surface.commits==commits+1,"real OS swipe once forward");shot(mode.key+"-after-next");
  hold(w*.15f,w*.58f,y);shot(mode.key+"-half-previous");cancelHold();waitFor(()->!reader.surface.animating(),3,"previous cancel");swipe(w*.15f,y,w*.85f,y,450);assertTrue(reader.surface.frame.pageIndex==2,"real OS swipe backward");
  touch(w*.84f,h*.4f,w*.84f,h*.4f,0,false);if(mode==PageTurnMode.NONE)assertTrue(!reader.surface.animating()&&reader.surface.frame.pageIndex==3,"none tap immediate");waitFor(()->!reader.surface.animating(),3,"tap complete");assertTrue(reader.surface.frame.pageIndex==3,"tap advances");touch(w*.16f,h*.4f,w*.16f,h*.4f,0,false);waitFor(()->!reader.surface.animating(),3,"tap back");assertTrue(reader.surface.frame.pageIndex==2,"tap backward");
  page(2);int rapid=reader.surface.commits;ui(()->{reader.surface.turn(1);reader.surface.turn(1);});waitFor(()->!reader.surface.animating(),3,"rapid settles");assertTrue(reader.surface.commits==rapid+(mode==PageTurnMode.NONE?2:1),"rapid taps serialize or immediately commit in none");page(2);int paused=reader.anchor;ui(()->{reader.surface.turn(1);reader.surface.suspendRendering();});assertTrue(mode==PageTurnMode.NONE||reader.anchor==paused,"pause cancels pending turn");ui(()->reader.surface.resumeRendering());page(2);
  int previous=reader.anchor;touch(w*.5f,h*.4f,w*.5f,h*.4f,0,false);assertTrue(reader.menuVisible&&reader.anchor==previous,"center toggles menu only");ui(()->reader.showSettings());shot(mode.key+"-settings-day");ui(()->{reader.settings.night=true;reader.settings.save();reader.surface.invalidatePageImages();reader.showSettings();});shot(mode.key+"-settings-night");ui(()->{reader.settings.night=false;reader.settings.save();reader.surface.invalidatePageImages();reader.hideOverlays();});
  waitFor(()->reader.layouts.containsKey(1),20,"neighbor layout");page(reader.surface.frame.layout.pages.size()-1);ui(()->reader.surface.turn(1));waitFor(()->!reader.surface.animating()&&reader.index==1,5,"cross chapter next "+mode);waitFor(()->reader.layouts.containsKey(0),20,"previous chapter ready");ui(()->reader.surface.turn(-1));waitFor(()->!reader.surface.animating()&&reader.index==0,5,"cross chapter back "+mode);
  int a=reader.anchor;ui(()->reader.showSettings());assertTrue(reader.anchor==a,"menu keeps offset");ui(()->reader.hideOverlays());
  record("mode_"+mode.key,new JSONObject().put("changed_pixels",changed).put("gesture_checks",true).put("cross_chapter",true).put("draw_cpu_mean_ms",reader.surface.animationFrames==0?0:reader.surface.animationNanos/1e6/reader.surface.animationFrames));
 }


 void regression()throws Exception{
  select(PageTurnMode.SIMULATION);page(2);int offset=reader.anchor;ui(()->{reader.settings.font=30;reader.settings.spacing=2;reader.settings.serif=true;reader.settingChanged();});ready();ReaderPaginator.Page p=reader.surface.frame.layout.pages.get(reader.surface.frame.pageIndex);assertTrue(reader.anchor==offset&&p.start<=offset&&offset<p.end,"font reflow keeps exact text offset");coverage(reader.surface.frame.layout);ui(()->{reader.settings.night=true;reader.settings.save();reader.surface.invalidatePageImages();});SystemClock.sleep(200);swipe(reader.surface.getWidth()*.85f,reader.surface.getHeight()*.25f,reader.surface.getWidth()*.15f,reader.surface.getHeight()*.25f,400);shot("simulation-large-font-night");record("reflow_large_font_night",true);
  for(int font:new int[]{16,20,30}){ReaderSettings settings=new ReaderSettings(getTargetContext());settings.font=font;ReaderPaginator layout=new ReaderPaginator("短段。\n\n"+repeat("长段落，完整连续正文😀。",80)+"\n\n尾段。",repeat("长标题",14),reader.width,reader.height,reader.getResources().getDisplayMetrics().density,reader.getResources().getDisplayMetrics().scaledDensity,settings);coverage(layout);}record("long_title_unicode_font_matrix",3);
  ReaderActivity.ChapterSource source=reader.source;ReaderSurface.Frame frame=reader.surface.frame;reader.prefetcher.cancel();reader.source=(b,id)->{throw new IOException("controlled chapter failure");};ui(()->{reader.chapters.remove(4);reader.layouts.remove(4);reader.open(4,0);});waitFor(()->!reader.busy,10,"failed chapter");assertTrue(reader.surface.frame==frame&&reader.retry!=null,"chapter failure retains frame and retry");reader.source=source;ui(()->reader.retry.run());ready();assertTrue(reader.index==4,"retry opens requested chapter");record("chapter_failure_and_retry",true);
  JSONArray full=reader.directory;ui(()->{JSONArray shortened=new JSONArray();for(int i=0;i<5;i++)shortened.put(full.optJSONObject(i));reader.directory=shortened;reader.chapters.remove(5);reader.layouts.remove(5);ReaderSurface.Frame f=reader.surface.frame;reader.commit(new ReaderSurface.Frame(f.id,f.title,4,5,f.layout,f.layout.pages.size()-1));reader.surface.turn(1);});waitFor(()->reader.index==5&&!reader.busy,40,"cached catalog end discovers next chapter");assertTrue(reader.directory.length()==full.length()&&!reader.chapter.optString("text").isEmpty(),"live catalog refresh and next chapter text");record("stale_catalog_end_refresh_still_works",true);
 }
 void cold(String phase)throws Exception{
  File saved=new File(output,"cold-state.json");LocalLibrary library=new LocalLibrary(getTargetContext());Bundle result=new Bundle();
  if(phase.equals("cold-restore")){JSONObject state;try(InputStream in=new FileInputStream(saved)){state=new JSONObject(new String(ProtocolCrypto.read(in),"UTF-8"));}restorePrefs(state.getJSONObject("prefs"));JSONObject position=state.getJSONObject("position");library.progress(book,position.optString("chapter"),position.optInt("offset"),position.optInt("index"),position.optInt("total"),position.optString("title"));File bookmarks=new File(output,"original-bookmarks.json");if(bookmarks.exists()){JSONArray rows;try(InputStream input=new FileInputStream(bookmarks)){rows=new JSONArray(new String(ProtocolCrypto.read(input),"UTF-8"));}android.database.sqlite.SQLiteDatabase sql=library.getWritableDatabase();sql.beginTransaction();try{sql.delete("bookmarks","book=?",new String[]{book});for(int i=0;i<rows.length();i++){JSONObject row=rows.getJSONObject(i);ContentValues values=new ContentValues();values.put("book",row.getString("book"));values.put("chapter",row.getString("chapter"));values.put("offset",row.getInt("offset"));values.put("title",row.getString("title"));values.put("created",row.getLong("created"));sql.insertOrThrow("bookmarks",null,values);}sql.setTransactionSuccessful();}finally{sql.endTransaction();}}record("original_user_settings_and_position_restored",true);}
  else if(phase.equals("cold-seed")){JSONObject position=library.progress(book);JSONObject state=new JSONObject().put("prefs",new JSONObject(getTargetContext().getSharedPreferences("ReaderActivity",0).getAll())).put("position",position);try(Writer writer=new OutputStreamWriter(new FileOutputStream(saved),"UTF-8")){writer.write(state.toString());}ReaderSettings settings=new ReaderSettings(getTargetContext());settings.pageTurnMode=PageTurnMode.SIMULATION;settings.save();getTargetContext().getSharedPreferences("ReaderActivity",0).edit().putString("page_turn_mode","simulation").commit();record("cold_seed",true);}
  else{JSONObject state;try(InputStream in=new FileInputStream(saved)){state=new JSONObject(new String(ProtocolCrypto.read(in),"UTF-8"));}try{assertTrue(new ReaderSettings(getTargetContext()).pageTurnMode==PageTurnMode.SIMULATION,"mode survives fresh process");launchMain();reader=(ReaderActivity)startActivitySync(new Intent(getTargetContext(),ReaderActivity.class).putExtra("book_id",book).putExtra("book_name","我在精神病院学斩神").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));ready();JSONObject position=state.getJSONObject("position");assertTrue(reader.anchor==position.optInt("offset")&&reader.chapter.optString("id").equals(position.optString("chapter")),"cold process exact reading location");assertTrue(reader.surface.activeMode==PageTurnMode.SIMULATION,"cold surface uses saved mode");shot("cold-reader");record("cold_process_mode_and_exact_position",true);}finally{if(reader!=null)ui(()->reader.finish());restorePrefs(state.getJSONObject("prefs"));JSONObject position=state.getJSONObject("position");library.progress(book,position.optString("chapter"),position.optInt("offset"),position.optInt("index"),position.optInt("total"),position.optString("title"));}}
  try(Writer w=new OutputStreamWriter(new FileOutputStream(new File(output,phase+".json")),"UTF-8")){w.write(new JSONObject().put("success",true).put("checks",checks).toString(2));}result.putString("stream","PASS "+phase);finish(Activity.RESULT_OK,result);
 }
 public void onStart(){output=new File(getTargetContext().getFilesDir(),"page-turn-evidence");output.mkdirs();String selected=args.getString("mode","all");if(selected.startsWith("cold-")){try{cold(selected);}catch(Throwable e){Bundle failed=new Bundle();failed.putString("stream",android.util.Log.getStackTraceString(e));finish(Activity.RESULT_CANCELED,failed);}return;}Bundle result=new Bundle();Throwable failure=null;try{db=new LocalLibrary(getTargetContext());originalPosition=db.progress(book);originalPrefs=new JSONObject(getTargetContext().getSharedPreferences("ReaderActivity",0).getAll());protocol();assertTrue(PageTurnMode.parse("obsolete")==PageTurnMode.COVER,"invalid setting defaults to cover");record("default_migration",true);launchReader();for(PageTurnMode mode:PageTurnMode.values())if(selected.equals("all")||selected.equals(mode.key))oneMode(mode);if(selected.equals("all")||selected.equals("regression"))regression();
  // Activity reconstruction restores the new stable preference without a layout offset change.
  select(PageTurnMode.SLIDE);int anchor=reader.anchor;String chapter=reader.chapter.optString("id");ActivityMonitor monitor=addMonitor(ReaderActivity.class.getName(),null,false);ui(()->reader.recreate());ReaderActivity recreated=(ReaderActivity)monitor.waitForActivityWithTimeout(10000);removeMonitor(monitor);assertTrue(recreated!=null,"activity recreated");reader=recreated;ready();assertTrue(reader.settings.pageTurnMode==PageTurnMode.SLIDE&&reader.anchor==anchor&&chapter.equals(reader.chapter.optString("id")),"recreate restores mode and exact position");record("recreation_mode_and_position",true);
 }catch(Throwable e){failure=e;try{record("failure",android.util.Log.getStackTraceString(e));shot("failure");}catch(Exception ignored){}}finally{try{if(reader!=null)ui(()->reader.finish());if(originalPrefs!=null)restorePrefs(originalPrefs);if(originalPosition!=null)db.progress(book,originalPosition.optString("chapter"),originalPosition.optInt("offset"),originalPosition.optInt("index"),originalPosition.optInt("total"),originalPosition.optString("title"));try(Writer out=new OutputStreamWriter(new FileOutputStream(new File(output,"turn-results-"+selected+".json")),"UTF-8")){out.write(new JSONObject().put("device",Build.MODEL).put("success",failure==null).put("checks",checks).toString(2));}}catch(Throwable e){failure=e;}}
 result.putString("stream",(failure==null?"PASS ":"FAIL ")+checks.length()+" checks"+(failure==null?"":"\n"+android.util.Log.getStackTraceString(failure)));finish(failure==null?Activity.RESULT_OK:Activity.RESULT_CANCELED,result);}
}
